 const currentPlan=()=>{const selected=plan(project(),bridge.state.selected);return selected?.environmentId===env()?.id?selected:planFor(project(),env()?.id,bridge.state.selected)||rs().find(r=>r.id===activeId)||inLens(rs())[0]||rs()[0]};
