 const chapterContext=()=>({work:'Place the current component, define recovery, and name its operating responsibilities.',model:'Trace placements, supporting services, runtime routes, and security enforcement in this environment.',validate:'Resolve unplaced components, fragile dependencies, unsupported recovery, and missing operating evidence.',output:'Carry deployment locations, operating plans, assumptions, and exercise gaps into the final architecture review.'}[bridge.state.tab]);
 function error(message,conflict=false){const e=document.querySelector('#rt-dialog-error')||document.querySelector('#rt-page-error');if(e){e.hidden=false;e.innerHTML=esc(message)+(conflict?B('reload','Load latest project'):'');e.scrollIntoView({block:'nearest'})}bridge.toast(message)}
