 function dialog(title,body,type,extra={}){if(presentAssistant(type,title,body))return;close(true);context={type,...extra};const e=openDialog({className:'l-dialog rt-dialog',labelledBy:'rt-dialog-title',html:'<header><div><span class="eyebrow">Chapter 10 / '+esc(bridge.state.tab)+' / '+esc((env()?.ref||'Project'))+'</span><h2 id="rt-dialog-title">'+esc(title)+'</h2></div>'+B('close','×','',{'aria-label':'Close dialog'})+'</header><div id="rt-dialog-error" class="l-error" role="alert" hidden></div>'+body+'<div class="l-discard" hidden><p>Discard your unsaved changes?</p>'+B('keep','Keep editing')+B('discard','Discard changes')+'</div>',onCancel:()=>close(),closeSelector:null});opener=e.opener;}
