 function step(index){const f=document.querySelector('#rt-editor');if(!f)return;f.querySelectorAll('[data-rt-panel]').forEach(e=>e.hidden=Number(e.dataset.rtPanel)!==index);f.querySelectorAll('[data-rt-step]').forEach(e=>{e.classList.toggle('active',Number(e.dataset.rtStep)===index);e.setAttribute('aria-pressed',String(Number(e.dataset.rtStep)===index))});f.querySelector('[data-rt-panel="'+index+'"] input,[data-rt-panel="'+index+'"] textarea,[data-rt-panel="'+index+'"] select')?.focus()}
