 // The plan editor's rows, read back as the plan's targets and schedule; its open placement kept beside its other open fields.
 function planRaw(f,raw){const fd=new FormData(f),rows=prefix=>[...new Set([...fd.keys()].filter(k=>k.startsWith(prefix+'-')).map(k=>k.slice(prefix.length+1)))],get=k=>String(fd.get(k)??'');
  raw.targets=rows('targetKind').filter(i=>get('targetKind-'+i)).map(i=>({kind:get('targetKind-'+i),driverId:get('targetDriver-'+i),operator:get('targetOperator-'+i),value:get('targetValue-'+i),unit:get('targetUnit-'+i),window:get('targetWindow-'+i),basis:get('targetBasis-'+i),confirmed:fd.has('targetConfirmed-'+i)}));
  const ws=rows('windowKind').filter(i=>get('windowKind-'+i)).map(i=>({kind:get('windowKind-'+i),name:get('windowName-'+i),start:get('windowStart-'+i),end:get('windowEnd-'+i),timeZone:get('windowZone-'+i),recurrence:get('windowRecurrence-'+i),cutOff:get('windowCutOff-'+i),contents:get('windowContents-'+i),contractIds:get('windowContracts-'+i).split(/[\s,;]+/).filter(Boolean),onlineDuring:get('windowOnline-'+i),driverId:get('windowDriver-'+i)}));
  raw.schedule={serviceHours:raw.serviceHours||'',basis:raw.scheduleBasis||'',maintenanceWindows:ws.filter(w=>w.kind==='maintenance').map(w=>({name:w.name,start:w.start,end:w.end,timeZone:w.timeZone,recurrence:w.recurrence})),batchWindows:ws.filter(w=>w.kind==='batch').map(w=>({name:w.name,start:w.start,end:w.end,timeZone:w.timeZone,cutOff:w.cutOff,contents:w.contents,contractIds:w.contractIds,onlineDuring:w.onlineDuring,driverId:w.driverId}))};
  for(const k of Object.keys(raw))if(/^(target|window)[A-Z][A-Za-z]*-/.test(k))delete raw[k];delete raw.serviceHours;delete raw.scheduleBasis;
  const r=plan(project(),context.id||ghost?.objectId),open={...(r?.open||{})};if(fd.has('placementOpen'))open.placements={state:'not-stated'};else delete open.placements;raw.open=open;delete raw.placementOpen;return raw}
 function newPlanReady(){return !!env()&&runtimeInputs(project()).some(a=>!planFor(project(),env().id,a.id));}
