 function placementForm(l={},proposed=false){return '<form id="rt-placement-form">'+fPlacement('planId',l.planId||currentPlan()?.id,{options:rs().map(r=>[r.id,r.ref+' · '+r.title])})+fPlacement('zoneId',l.zoneId||'',{options:[['','Choose a zone'],...zs().map(z=>[z.id,z.ref+' · '+z.title])]})+'<div class="l-form-grid">'+fPlacement('role',l.id?l.role??'':'active',{options:[['','Not stated'],['active','Active capacity'],['standby','Standby candidate']]})+fPlacement('replicas',l.replicas??'')+'</div>'+fPlacement('basis',l.basis)+fPlacement('confirmed',l.confirmed)+'<p class="l-note">Replica counts describe the model. They do not establish actual capacity, health, or successful failover.</p>'+(proposed?fPlacement('reviewed',false)+B('preview-placement','Preview edited ghost'):'')+end(proposed?'Accept reviewed placement':'Save placement')+'</form>'}
