 function editPath(id,contractId=''){const r=runtimePath(project(),id)||{environmentId:env()?.id||'',contractId,mode:''},c=contract(project(),r.contractId),x=r.id?pathCrossing(project(),r):null,own=Array.isArray(r.boundaryIds),bref=b=>project().technology.boundaries.find(x=>x.id===b)?.ref||b;
  dialog(r.id?'Define '+r.id+' runtime path':'New runtime path',(c?'<p>'+esc(c.ref+' · '+c.title)+'</p>':'')+'<p>The schema, correlation, retry, and provider obligations remain in Chapter 8.</p><form id="rt-path-form">'+(r.id?'<input type="hidden" name="contractId" value="'+esc(r.contractId)+'"><input type="hidden" name="environmentId" value="'+esc(r.environmentId)+'">':'<div class="l-form-grid">'+fPath('contractId',r.contractId,{options:[['','Choose a contract'],...pathContracts()]})+fPath('environmentId',r.environmentId,{options:environments(project()).map(e=>[e.id,e.ref+' · '+e.title])})+'</div>')+fPath('route',r.route)+fPath('access',r.access)+fPath('owner',r.owner)+fPath('mode',r.mode??'')+fPath('startup',r.startup??'')+fPath('failureResponse',r.failureResponse)+'<p class="l-note">'+esc(x?x.derived.length?'Read from its contract, it crosses '+x.derived.map(bref).join(' and ')+(x.outside?', from outside the design':'')+'.':'Read from its contract, it crosses no trust boundary.':'What it crosses is read from its contract once it is saved.')+'</p>'+fPath('ownBoundaries',own)+fPath('boundaryIds',own?r.boundaryIds:x?.derived||[],{options:project().technology.boundaries.map(b=>[b.id,b.ref+' · '+b.title])})+fPath('grounds',groundText(r))+end(r.id?'Save runtime path':'Create runtime path')+'</form>','path',{id:r.id})}
 // AIW's proposed plans and paths (round 12, D-13, DM-17): kept as the person's or dismissed with a reason; a retired one
